INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(18601, 'Jeremiah 31:23', 'Jeremiah', 31, 23, '&nbsp;مالِک خُدائ ربُ الافواج، د بنى اِسرائيلو خُدائ پاک فرمائى، ”کله چې زۀ هغوئ د غلامۍ نه واپس راولم، په يهوداه او د هغې په ښارونو کښې به هغوئ بيا داسې ووائى چې، اے د صداقت ځايه، اے مقدس غره، مالِک خُدائ دې تا له برکت درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18602, 'Jeremiah 31:24', 'Jeremiah', 31, 24, '&nbsp;ښاريان او زمينداران او شپونکى به د خپلو رمو سره په شريکه د يهوداه په مُلک کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18603, 'Jeremiah 31:25', 'Jeremiah', 31, 25, '&nbsp;زۀ به ستړو ستومانو ته طاقت ورکړم او مړاوى شوى به تازه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18604, 'Jeremiah 31:26', 'Jeremiah', 31, 26, '&nbsp;نو کله چې زۀ راپاڅېدم او خپلې سترګې مې پرانستلې، نو زۀ پوهه شوم چې په خوږ خوب اودۀ وم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18605, 'Jeremiah 31:27', 'Jeremiah', 31, 27, '&nbsp;مالِک خُدائ فرمائى چې، ”هغه ورځ راروانه ده چې زۀ به د اِسرائيل او يهوداه او د هغوئ د ځناورو نسلونه زيات کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18606, 'Jeremiah 31:28', 'Jeremiah', 31, 28, '&nbsp;او لکه څنګه چې ما هغوئ د بېخ نه راويستل، او ټوکړې ټوکړې مې کړل، او راومې غورزول، او تباه مې کړل او افتونه مې پرې نازل کړل، نو دغه شان به زۀ هغوئ دوباره آباد او قائم کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18607, 'Jeremiah 31:29', 'Jeremiah', 31, 29, '&nbsp;په هغه ورځو کښې به نور خلق داسې نۀ وائى چې، تراوۀ انګور يې پلارانو وخوړل، او غاښونه يې د بچو وبرېښېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18608, 'Jeremiah 31:30', 'Jeremiah', 31, 30, '&nbsp;خو هر سړے به د خپلې ګناه په وجه مړ کيږى، هر څوک چې تراوۀ انګور وخورى هم د هغۀ غاښونه به برېښيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18609, 'Jeremiah 31:31', 'Jeremiah', 31, 31, '&nbsp;مالِک خُدائ فرمائى چې، ”هغه وخت راروان دے چې کله زۀ د اِسرائيل او د يهوداه د خلقو سره يو نوے لوظ وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18610, 'Jeremiah 31:32', 'Jeremiah', 31, 32, '&nbsp;دا به د هغه لوظ په شان نۀ وى کوم چې ما د هغوئ د پلار نيکۀ سره کړے وو کله چې ما هغوئ د لاس نه ونيول او د مِصر نه مې بهر وويستل، ځکه چې هغوئ ما سره کړے لوظ مات کړو، کۀ څۀ هم چې زما مثال هغوئ ته د وفادار خاوند په شان وو. مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18611, 'Jeremiah 31:33', 'Jeremiah', 31, 33, '&nbsp;خو دا هغه نوے لوظ دے کوم به چې زۀ پس د دې نه د بنى اِسرائيلو د قبيلې سره وکړم، زۀ به خپل شريعت د هغوئ په مازغو کښې واچوم او د هغوئ په زړونو به يې وليکم. زۀ به د هغوئ خُدائ پاک يم او هغوئ به زما بنده ګان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18612, 'Jeremiah 31:34', 'Jeremiah', 31, 34, '&nbsp;نور به د هغوئ نه يو کس هم خپل ګاونډى ته، او يا خپل ورور ته دا تعليم نۀ ورکوى چې مالِک خُدائ وپېژنه، ځکه چې د وړو نه واخله تر لويو پورې به هغوئ ټول ما پېژنى، مالِک خُدائ داسې فرمائى. زۀ به د هغوئ شرارتونه معاف کړم او د هغوئ ګناهونه به نور نۀ يادوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18613, 'Jeremiah 31:35', 'Jeremiah', 31, 35, '&nbsp;مالِک خُدائ داسې فرمائى، هغه څوک چې نمر په دې مقرروى چې د ورځې وځليږى، او هغه چا چې سپوږمۍ او ستورى مقرر کړل چې د شپې وځليږى، څوک چې سمندر راپاڅوى چې د هغې چپې شور وکړى نو د هغۀ نوم مالِک خُدائ ربُ الافواج دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18614, 'Jeremiah 31:36', 'Jeremiah', 31, 36, '&nbsp;مالِک خُدائ داسې فرمائى چې، ”ترڅو پورې د کائنات دا نظام موجود وى، نو تر هغه وخته پورې به د بنى اِسرائيلو قوم زما د وړاندې قائم وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18615, 'Jeremiah 31:37', 'Jeremiah', 31, 37, '&nbsp;مالِک خُدائ داسې فرمائى چې، ”لکه څنګه چې د آسمان د ناپ تول اندازه نۀ شى لګولے او د زمکې د بنياد اندازه نۀ شى معلومولے نو زۀ به هم د اِسرائيل د ګناهونو په وجه د هغوئ نه اِنکار ونۀ کړم.“ دا د مالِک خُدائ فرمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18616, 'Jeremiah 31:38', 'Jeremiah', 31, 38, '&nbsp;”هغه ورځ راتلونکى ده،“ مالِک خُدائ فرمائى چې، ”کله چې دا ښار د حنن‌ايل د برج نه واخله تر د ګوټ د دروازې پورې به دوباره زما دپاره آباد شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18617, 'Jeremiah 31:39', 'Jeremiah', 31, 39, '&nbsp;او د هغه ځائ نه به سيدها د ښار حدود جارب غونډۍ پورې ورسيږى او بيا به د جوعه طرف ته راتاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18618, 'Jeremiah 31:40', 'Jeremiah', 31, 40, '&nbsp;نو بيا به ټوله دره چرته چې د مړو لاشونه او ايرې غورزولے شى او هغه ټوله زمکه د کومې مېدانونه چې د قِدرون د درې د نمرخاتۀ پورې پراتۀ دى، او د آسونو د دروازې پورې، ټوله به مالِک خُدائ ته مقدسه وى. دا ښار به هيڅکله بيا د بېخ نه راونۀ ويستلے شى او نۀ به تباه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18619, 'Jeremiah 32:1', 'Jeremiah', 32, 1, '&nbsp;د يهوداه د مُلک د صدقياه بادشاه د بادشاهۍ په لسم کال کوم چې اتلسم کال د نبوکدنضر د بادشاهۍ وو، د مالِک خُدائ کلام يرمياه ته ورکړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18620, 'Jeremiah 32:2', 'Jeremiah', 32, 2, '&nbsp;په هغه وخت کښې چې د بابل د بادشاه لښکرو د يروشلم نه ګېره اچولې وه نو يرمياه په دې ورځو کښې د يهوداه د شاهى محل دننه په فوجى چاوڼۍ کښې بند وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18621, 'Jeremiah 32:3', 'Jeremiah', 32, 3, '&nbsp;نو صدقياه بادشاه هغه هلته قېد کړو او ورته يې ووئيل چې، ”تۀ ولې دا پېشګوئې کوې؟ چې مالِک خُدائ فرمائى چې زۀ دا ښار د بابل بادشاه ته حواله کوم نو بيا به هغه په دې ښار قبضه وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18622, 'Jeremiah 32:4', 'Jeremiah', 32, 4, '&nbsp;صدقياه بادشاه به د بابليانو د لاس نه ونۀ تښتى، او هغه به په يقين سره د بابل بادشاه ته حواله کړے شى، او هغه به دۀ سره مخامخ خبرې وکړى او دے به يې په خپلو سترګو سره وګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18623, 'Jeremiah 32:5', 'Jeremiah', 32, 5, '&nbsp;هغه به صدقياه بابل ته بوځى او هغه به تر هغې پورې هلته پاتې وى چې ترڅو مې ورسره خپل عمل نۀ وى کړے، مالِک خُدائ فرمائى. کۀ چرې تۀ د بابليانو خلاف جنګ وکړې، نو تۀ به کامياب نۀ شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18624, 'Jeremiah 32:6', 'Jeremiah', 32, 6, '&nbsp;يرمياه وفرمائيل چې، ”نو په دغه وخت کښې د مالِک خُدائ کلام په ما نازل شو چې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18625, 'Jeremiah 32:7', 'Jeremiah', 32, 7, '&nbsp;ستا د ترۀ زوئ حنم‌ايل د سلوم زوئ به تا له راشى او درته به وائى چې په عنتوت کښې زما زمکه واخله، ځکه چې تۀ زما نزدې خپلوان يې نو اول د اخستو حق ستا دے او دا ستا فرض هم جوړيږى چې تۀ يې واخلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18626, 'Jeremiah 32:8', 'Jeremiah', 32, 8, '&nbsp;نو بيا لکه څنګه چې مالِک خُدائ فرمائيلى وُو، زما د ترۀ زوئ حنم‌ايل فوجى چاوڼۍ ته راغلو او هغۀ ووئيل چې په عنتوت کښې زما زمکه واخله کومه چې د بنيامين په علاقه کښې ده. ځکه چې دا ستا حق دے چې تۀ يې خلاصه کړې او د خپل ځان دپاره يې واخلې. نو زۀ په دې پوهه شوم چې مالِک خُدائ ما سره په هم دې حقله خبره کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18627, 'Jeremiah 32:9', 'Jeremiah', 32, 9, '&nbsp;نو بيا ما هغه زمکه د ترۀ زوئ حنم‌ايل نه د اوولسو سپينو زرو سيکو په بيعه واخستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18628, 'Jeremiah 32:10', 'Jeremiah', 32, 10, '&nbsp;ما د ګواهانو په وړاندې د هغه زمکې انتقال نامه وليکله او په هغې مې دستخط وکړو او مهر مې پرې ولګولو او هغه سپين زر مې په تله کښې وتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18629, 'Jeremiah 32:11', 'Jeremiah', 32, 11, '&nbsp;بيا ما د مهر شوې انتقال نامې چې د خرڅولو ټول اصُول او شرائط په کښې درج شوى وُو او هم يوه غېر مهر شوې کاپې راواخسته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18630, 'Jeremiah 32:12', 'Jeremiah', 32, 12, '&nbsp;او دواړه مې باروک د نيرياه زوئ او د محسياه نمسى ته د حنم‌ايل او د هغه ګواهانو چا چې په انتقال دستخط کړے وو او د هغه ټولو خلقو په موجودګۍ کښې چې په فوجى چاوڼۍ کښې ناست وُو حواله کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18631, 'Jeremiah 32:13', 'Jeremiah', 32, 13, '&nbsp;د هغه ټولو کسانو په مخکښې ما باروک ته هدايت ورکړو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18632, 'Jeremiah 32:14', 'Jeremiah', 32, 14, '&nbsp;مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، د سودا دا دواړه کاغذونه واخله چې په يو باندې مهر شته او په بل نشته او دواړه په خاورين منګى کښې واچوه ترڅو چې د ډېر وخت دپاره محفوظ پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18633, 'Jeremiah 32:15', 'Jeremiah', 32, 15, '&nbsp;نو مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، په دې مُلک کښې به بيا کورونه، پټى او د انګورو باغونه اخستل کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18634, 'Jeremiah 32:16', 'Jeremiah', 32, 16, '&nbsp;”د هغې نه وروستو کله چې ما د زمکې کاغذونه باروک د نيرياه زوئ له ورکړل نو بيا ما دُعا وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18635, 'Jeremiah 32:17', 'Jeremiah', 32, 17, '&nbsp;اے مالِکه قادر مطلق خُدايه، تا په خپل لوئ طاقت او قُدرت سره او په خپل زورَور لاس سره آسمان او زمکه جوړ کړل. ستا دپاره يو کار هم ناممکن نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18636, 'Jeremiah 32:18', 'Jeremiah', 32, 18, '&nbsp;تۀ زرګونو خلقو سره مينه کوې، خو د مور پلار د ګناهونو په وجه تۀ د هغوئ بچو له سزا ورکوې. اے عظيم او طاقتور خُدايه، د چا نوم چې مالِک خُدائ ربُ الافواج دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18637, 'Jeremiah 32:19', 'Jeremiah', 32, 19, '&nbsp;ستا مقصد عظيم او ستا کارونه زورَور دى. ستا سترګې د انسان ټولې لارې وينى، او تۀ هر يو ته د خپل چال چلن او عمل په مطابق اجر ورکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18638, 'Jeremiah 32:20', 'Jeremiah', 32, 20, '&nbsp;تا په مِصر کښې معجزې او حېرانونکى کارونه کړى دى، او ستا دا سلسله په بنى اِسرائيلو او په ټولو انسانانو کښې تر ننه پورې راروانه ده، او تر نن ورځ پورې تا خپل نوم ته جلال ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18639, 'Jeremiah 32:21', 'Jeremiah', 32, 21, '&nbsp;تا په خپل زورَور لاس، لوئ دهشت، عجيبه کارونو او معجزو سره خپل خلق بنى اِسرائيل د مِصر نه راوويستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18640, 'Jeremiah 32:22', 'Jeremiah', 32, 22, '&nbsp;تا هغوئ ته هغه زرخيزه زمکه ورکړه د کومې دې چې د هغوئ د پلار نيکۀ سره وړاندې وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18641, 'Jeremiah 32:23', 'Jeremiah', 32, 23, '&nbsp;خو چې کله زمونږ پلار نيکۀ په دې مُلک کښې داخل شول او په دې يې قبضه وکړه نو هغوئ نۀ ستا واورېدل او نۀ يې ستا د شريعت پيروى وکړه. او هغوئ په هغه څۀ باندې عمل ونۀ کړو د کوم چې ورله تا حکم کړے وو. نو بيا ځکه تا دا ټول افتونه په هغوئ رانازل کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18642, 'Jeremiah 32:24', 'Jeremiah', 32, 24, '&nbsp;وګورئ چې بابليانو د ښار د نيولو دپاره ګېرچاپېره څنګه د خاورو ډېرى جوړ کړل. د جنګ، قحط او وبا په وجه به دا ښار بابليانو ته څوک چې پرې حمله کوى حواله شى. تا چې څۀ وئيلى وُو نو هغه کارونه وشول، اوس يې په خپله وګوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18643, 'Jeremiah 32:25', 'Jeremiah', 32, 25, '&nbsp;خو اے مالِکه خُدايه زما ربه تۀ هغه ذات يې چې ما ته دې حُکم راکړو چې د ګواهانو په مخکښې هغه زمکه واخله، سره د دې چې د ښار حالت داسې خراب وو چې بابليانو نيولو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18644, 'Jeremiah 32:26', 'Jeremiah', 32, 26, '&nbsp;نو بيا د مالِک خُدائ له طرفه دا پېغام يرمياه ته راغلو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18645, 'Jeremiah 32:27', 'Jeremiah', 32, 27, '&nbsp;”زۀ مالِک قادر مطلق خُدائ يم، او د ټولو مخلوقاتو رب العالمين يم. آيا داسې کار شته چې د هغې کول زما دپاره ناممکن وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18646, 'Jeremiah 32:28', 'Jeremiah', 32, 28, '&nbsp;نو ځکه زۀ دا ښار د بابل بادشاه نبوکدنضر او د هغۀ لښکر ته حواله کوم، نو هغوئ به دا قبضه کړى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18647, 'Jeremiah 32:29', 'Jeremiah', 32, 29, '&nbsp;او د دېوال نه اخوا بابليان به راشى او په دې ښار به اور بل کړى. هغوئ به ټول کورونه وسوزوى، چرته چې خلقو زۀ په دې غصه کړم چې د کوټو په چتونو يې بعل ته خوشبويۍ وسوزولې او نورو معبودانو ته يې د څښلو نذرانې پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18648, 'Jeremiah 32:30', 'Jeremiah', 32, 30, '&nbsp;نو د اِسرائيل او د يهوداه خلقو د ځوانۍ نه واخله تر اوسه پورې د شرارت نه بغېر بل کوم کار نۀ دے کړے او هر وخت يې زۀ په خپل کردار سره غصه کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18649, 'Jeremiah 32:31', 'Jeremiah', 32, 31, '&nbsp;د کومې ورځې نه چې دا ښار جوړ شوے دے نو د هغې ورځې نه تر ننه پورې زۀ دې خلقو غصه کړے او په قهر کړے يم. نو ځکه زۀ دا ښار د خپل مخ نه اخوا کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18650, 'Jeremiah 32:32', 'Jeremiah', 32, 32, '&nbsp;د اِسرائيل او د يهوداه خلقو زۀ په هغه ټولو شرارتونو کوم چې دوئ وکړل غصه کړم کۀ هغه بادشاهانو، آفسرانو، مشرانو، اِمامانو او کۀ نبيانو هم کړى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18651, 'Jeremiah 32:33', 'Jeremiah', 32, 33, '&nbsp;زما خلقو ما ته شا کړې ده، او ما ته د کتلو نه يې اِنکار کړے دے، سره د دې چې ما بار بار په نرمۍ سره هغوئ ته تعليم ورکړے دے، خو هغوئ زما خبرو ته غوږ نۀ دے نيولے او نۀ يې زما اصلاح قبوله کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18652, 'Jeremiah 32:34', 'Jeremiah', 32, 34, '&nbsp;هغوئ خپل حرام بُتان زما په کور کښې اېښى دى، کوم کور چې زما د عبادت دپاره جوړ شوے وو او هغوئ په دې زما کور پليت کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18653, 'Jeremiah 32:35', 'Jeremiah', 32, 35, '&nbsp;هغوئ د هنوم په وادۍ کښې بعل ته علاقائى عبادتخانې د دې دپاره جوړې کړې چې مولک بُت ته خپل زامن او لوڼه قربانى کړى. نۀ خو ما هغوئ له د داسې کولو حُکم ورکړو او نۀ زما ذهن ته داسې خرابه خبره راغلې ده چې هغوئ به داسې په بد او پليت کار کولو سره يهوداه ګناه ګار کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18654, 'Jeremiah 32:36', 'Jeremiah', 32, 36, '&nbsp;”تاسو وايئ چې، دا ښار به د جنګ، قحط، او وبا په وجه د بابل بادشاه قبضه کړى، خو مالِک خُدائ د بنى اِسرائيلو خُدائ پاک د دې ښار په حقله فرمائى چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18655, 'Jeremiah 32:37', 'Jeremiah', 32, 37, '&nbsp;زۀ به په يقين سره خپل غوره شوى خلق د ټولو مُلکونو نه واپس دې ځائ ته راولم کوم چې ما د خپلې غصې او لوئ غضب په وخت کښې خوارۀ وارۀ کړى وُو. او هغوئ به واپس راولم او په دې ځائ کښې به نور په امن او سکون سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18656, 'Jeremiah 32:38', 'Jeremiah', 32, 38, '&nbsp;بيا به هغوئ زما خلق وى او زۀ به د هغوئ خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18657, 'Jeremiah 32:39', 'Jeremiah', 32, 39, '&nbsp;زۀ به هغوئ ته د زړۀ او د سوچ يووالے ورکړم چې د خپل ځان د خوشحالۍ او د خپل نسل د آبادۍ او سکون دپاره به زما نه همېشه يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18658, 'Jeremiah 32:40', 'Jeremiah', 32, 40, '&nbsp;زۀ به د هغوئ سره ابدى لوظ وکړم، چې زۀ به د هغوئ سره ښېګړه کول هيڅکله نۀ پرېږدم. او زۀ به خپله يره د هغوئ په زړُونو کښې واچوم، ترڅو چې نور هغوئ ما نه لرې لاړ نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18659, 'Jeremiah 32:41', 'Jeremiah', 32, 41, '&nbsp;هغوئ ته په برکت ورکولو سره ما ته خوشحالى ملاويږى، او زۀ به په وفادارۍ او پوره زړۀ سره هغوئ په دې مُلک کښې دوباره آباد کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18660, 'Jeremiah 32:42', 'Jeremiah', 32, 42, '&nbsp;لکه څنګه چې ما په دې خلقو دا لوئ افت راوستو، نو دغه شان به زۀ دوئ ته هغه ټولې سوکالۍ هم ورکړم د کومې چې ما هغوئ سره وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18661, 'Jeremiah 32:43', 'Jeremiah', 32, 43, '&nbsp;نو يو ځل به بيا په دې مُلک کښې زمکې واخستلے شى، د کوم چې تاسو وايئ چې دا خو صحرا او بې‌کاره زمکه ده، بغېر د انسانانو او ځناورو، ځکه چې دا خو بابليانو ته په قبضه کښې ورکړے شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18662, 'Jeremiah 32:44', 'Jeremiah', 32, 44, '&nbsp;آو، د بنيامين په علاقه، د يروشلم په خوا او شا، د يهوداه په ښارونو، غريزه علاقو، د غرونو په کلو، مغربى صحراګانو او په نجب کښې به زمکې د سپينو زرو سيکو باندې اخستلے کيږى او مهر شوى انتقالونه او ګواهان به په کښې نيولے کيږى، ځکه چې زۀ به دا قوم د غلامۍ نه واپس راولم. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18663, 'Jeremiah 33:1', 'Jeremiah', 33, 1, '&nbsp;يرمياه چې لا د فوجيانو په چاوڼۍ کښې بند وو نو د مالِک خُدائ پېغام په دوېم ځل هغۀ ته راغلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18664, 'Jeremiah 33:2', 'Jeremiah', 33, 2, '&nbsp;”مالِک خُدائ چا چې، زمکه جوړه کړه، او هغې ته يې شکل ورکړو او قائمه يې کړه او د چا نوم چې مالِک خُدائ دے هغه فرمائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18665, 'Jeremiah 33:3', 'Jeremiah', 33, 3, '&nbsp;د مدد دپاره ما ته ووايه او زۀ به جواب درکړم او زۀ به تا ته هغه لوئ او پټ رازونه او خبرې څرګندې کړم چې تۀ پرې نۀ پوهېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18666, 'Jeremiah 33:4', 'Jeremiah', 33, 4, '&nbsp;نو مالِک خُدائ د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، تاسو د ښار کورونه او تر دې چې شاهى محل هم راوغورزولو د دې دپاره چې د دشمن د محاصرې او حملې په وخت کښې تاسو د هغې په ملبې خپل د خاورو ډېرو دېوالونه مضبوط کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18667, 'Jeremiah 33:5', 'Jeremiah', 33, 5, '&nbsp;د بابليانو سره په جنګ کولو کښې به دا ښار او د دې کورونه د خلقو د مړو د لاشونو نه ډک کړم. زۀ به دوئ په خپل قهر او غضب کښې تباه کړم. زۀ به د دې ښار نه د دوئ د ګناهونو په وجه خپل مخ پټ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18668, 'Jeremiah 33:6', 'Jeremiah', 33, 6, '&nbsp;خو باوجود د دې به هغه وخت راشى چې زۀ به د يروشلم زخمونو ته شفا ورکړم او هغې ته به حقيقى امن او سکون ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18669, 'Jeremiah 33:7', 'Jeremiah', 33, 7, '&nbsp;زۀ به يهوداه او اِسرائيل د غلامۍ نه واپس راولم او هغوئ به بيا هغه شان آباد کړم لکه څنګه چې هغوئ وړاندې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18670, 'Jeremiah 33:8', 'Jeremiah', 33, 8, '&nbsp;زۀ به هغوئ د هغه ټولو ګناهونو نه پاک کړم کوم چې هغوئ زما خِلاف کړى دى، او زۀ به د هغوئ هغه سرکشى معاف کړم کومه چې هغوئ زما خلاف کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18671, 'Jeremiah 33:9', 'Jeremiah', 33, 9, '&nbsp;نو بيا به دا ښار ما ته د ټولې دُنيا د خلقو په وړاندې خوشحالى، شُهرت، او عزت راکړى، کله چې دوئ د هغه ټولو ښۀ څيزونو په حقله واورى کوم چې زۀ د يروشلم سره کوم. او خلق به د دې ټول امن او آبادۍ نه متاثره شى او د يرې نه به په لړزان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18672, 'Jeremiah 33:10', 'Jeremiah', 33, 10, '&nbsp;مالِک خُدائ فرمائى چې، تاسو د دې ځائ په حقله وايئ چې، دا ځائ خو د صحرا په شان دے چې په کښې نه انسان او نه ځناور شته. خو د يهوداه ښارونه او د يروشلم کوڅې خالى دى کومې چې په ميرو بدلې شوې چې نۀ په کښې انسان او نۀ په کښې ځناور شته، نو يو ځل بيا به هلته،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18673, 'Jeremiah 33:11', 'Jeremiah', 33, 11, '&nbsp;د خوشحالۍ او د خندا آوازونه واورېدلے شى او په کښې به د ناوې او د زلمى آوازونه واورېدلے شى، او د هغوئ آوازونه چې د مالِک خُدائ په کور کښې د شکرانې نذرانې پېش کوى، واورېدلے شى. او هغوئ به داسې وائى چې، د مالِک خُدائ ربُ الافواج شُکر ګزارى وکړئ، ځکه چې هغه ښۀ دے، د هغۀ مينه نۀ ختمېدونکې ده. مالِک خُدائ دا فرمائى چې، زۀ به دا مُلک د غلامۍ نه واپس راولم لکه څنګه چې وړاندې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18674, 'Jeremiah 33:12', 'Jeremiah', 33, 12, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى، کۀ څۀ هم چې دا مُلک اوس د صحرا په شان دے او د انسانانو او ځناورو نه خالى دے خو په دې کښې به بيا د څرن زمکه راپېدا شى چې شپونکى به ورته خپلې رمې څرولو دپاره راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18675, 'Jeremiah 33:13', 'Jeremiah', 33, 13, '&nbsp;مالِک خُدائ فرمائى چې، د غريزه مُلک په ښارونو، او د غونډو په شا او خوا، او د نجب په صحرا، د بنيامين په علاقه کښې، د يروشلم په شا او خوا، او د يهوداه په ښارونو کښې به شپونکى يو ځل بيا خپل ګډورى وشمارى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18676, 'Jeremiah 33:14', 'Jeremiah', 33, 14, '&nbsp;مالِک خُدائ فرمائى چې، هغه وخت راتلونکے دے چې زۀ به خپله هغه مهربانه وعده پوره کړم چې کومه ما د يهوداه او د اِسرائيل سره کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18677, 'Jeremiah 33:15', 'Jeremiah', 33, 15, '&nbsp;په هغه وخت کښې به زۀ د داؤد د اولاد نه يوه صادقه څانګه راوټوکوم، هغه به په ټول مُلک کښې هغه کارونه کوى کوم چې د اِنصاف او صداقت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18678, 'Jeremiah 33:16', 'Jeremiah', 33, 16, '&nbsp;په هغه ورځو کښې به يهوداه بچ کړے شى او يروشلم به د سلامتۍ سره ژوند کوى. او دا هغه نوم دے چې په کوم سره به هغه ياديږى، مالِک خُدائ زمونږ خلاصونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18679, 'Jeremiah 33:17', 'Jeremiah', 33, 17, '&nbsp;مالِک خُدائ داسې فرمائى چې، د داؤد په اولاد کښې به همېشه يو کس د بنى اِسرائيلو په تخت ناست وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18680, 'Jeremiah 33:18', 'Jeremiah', 33, 18, '&nbsp;او هم داسې به اِمامان همېشه د ليوى قبيلې نه وى څوک به چې تل زما خِدمت کوى او ما ته به سوزېدونکې نذرانې، او د غلو نذرانې او قربانۍ پېش کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18681, 'Jeremiah 33:19', 'Jeremiah', 33, 19, '&nbsp;نو بيا د مالِک خُدائ پېغام يرمياه ته راغلو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18682, 'Jeremiah 33:20', 'Jeremiah', 33, 20, '&nbsp;”مالِک خُدائ فرمائى چې، کۀ چرې تاسو زما لوظ د ورځې او د شپې د مقرر شوى نظام په حقله ماتولے شئ، چې شپه او ورځ په خپل مقرر شوى وخت رانۀ شى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18683, 'Jeremiah 33:21', 'Jeremiah', 33, 21, '&nbsp;نو بيا به هغه وخت زما لوظ زما د خِدمتګار داؤد سره او زما لوظ د ليويانو سره چې زما اِمامان دى او زما په حضور کښې خِدمت کوى به هم ماتېدے شى، نو بيا به د داؤد اولاد کښې نور څوک نۀ وى چې د هغۀ په تخت بادشاهى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18684, 'Jeremiah 33:22', 'Jeremiah', 33, 22, '&nbsp;زۀ به د خپل خِدمتګار داؤد نسل او ليويان کوم چې زما اِمامان دى او زما په وړاندې خِدمت کوى د آسمان د ستورو او د سمندر د شګو په شان بې‌شمېره زيات کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18685, 'Jeremiah 33:23', 'Jeremiah', 33, 23, '&nbsp;مالِک خُدائ بل پېغام يرمياه ته ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18686, 'Jeremiah 33:24', 'Jeremiah', 33, 24, '&nbsp;”آيا تا د خلقو خبرو ته غوږ نۀ دے نيولے چې هغوئ وائى، مالِک خُدائ اوس هغه دوه قومونه رد کړى دى کوم چې اول هغۀ غوره کړى وُو؟ نو هغوئ زما د قوم سپکوالے کوى او د يو قوم په حيثيت يې نۀ منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18687, 'Jeremiah 33:25', 'Jeremiah', 33, 25, '&nbsp;خو مالِک خُدائ داسې فرمائى چې، کۀ چرې ما د ورځې او د شپې سره لوظ نۀ وو کړے او د زمکې او آسمان نظام مې نۀ وو جوړ کړے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18688, 'Jeremiah 33:26', 'Jeremiah', 33, 26, '&nbsp;نو بيا به زۀ د يعقوب او د خپل خِدمتګار داؤد اولاد نامنظور کړم، او نۀ به د يعقوب او د داؤد د اولاد نه څوک خوښ کړم چې د اِبراهيم، اِسحاق او يعقوب په اولاد حکومت وکړى. ځکه چې زۀ به هغوئ د غلامۍ نه واپس راولم او په هغوئ به رحم وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18689, 'Jeremiah 34:1', 'Jeremiah', 34, 1, '&nbsp;کله چې د بابل بادشاه نبوکدنضر او د هغۀ ټولو لښکرو او د هغۀ د بادشاهت د لاندې ټولو مُلکونو چې په يروشلم او د هغۀ په خوا او شا ښارونو باندې حمله کوله نو د مالِک خُدائ پېغام يرمياه ته ورکړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18690, 'Jeremiah 34:2', 'Jeremiah', 34, 2, '&nbsp;مالِک خُدائ د بنى اِسرائيلو خُدائ پاک يرمياه ته وفرمائيل چې، ”لاړ شه او د يهوداه بادشاه صدقياه ته ووايه چې، مالِک خُدائ فرمائى چې زۀ دا ښار د بابل بادشاه ته حواله کړم، او هغه به اوس دې ښار ته اور واچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18691, 'Jeremiah 34:3', 'Jeremiah', 34, 3, '&nbsp;تۀ به د هغۀ د ګرفتارى نه ونۀ تښتې بلکې په يقين سره به تۀ ګرفتار شې او هغۀ ته به حواله کړے شې. تۀ به د بابل بادشاه په خپلو سترګو ووينې، او هغه به تا سره مخامخ خبرې وکړى. او هغه به تا بابل ته جلاوطن کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18692, 'Jeremiah 34:4', 'Jeremiah', 34, 4, '&nbsp;نو بيا اے صدقياه د يهوداه بادشاه، ما ته غوږ شه. مالِک خُدائ ستا په حقله فرمائى چې، تۀ به په جنګ کښې قتل نۀ شې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18693, 'Jeremiah 34:5', 'Jeremiah', 34, 5, '&nbsp;بلکې تۀ به په خپل عام مرګ باندې مړ شې. څنګه چې خلقو ستا د پلار نيکۀ د جنازې د عزت دپاره خوشبو سوزوله څوک چې ستا نه وړاندې بادشاهان وُو، نو دغه شان به خلق ستا د جنازې د عزت دپاره خوشبو وسوزوى. او هغوئ به ماتم کوى او وائى به چې، افسوس، اے زمونږه بادشاه، تۀ مړ شوې. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18694, 'Jeremiah 34:6', 'Jeremiah', 34, 6, '&nbsp;نو بيا يرمياه پېغمبر دا پېغام د يهوداه بادشاه صدقياه ته په يروشلم کښې ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18695, 'Jeremiah 34:7', 'Jeremiah', 34, 7, '&nbsp;په هغه وخت کښې د بابل بادشاه لښکرو د يروشلم او د يهوداه د نورو ښارونو په خلاف جنګ کولو کوم چې لکيس او عزيقه وُو. صرف دا مضبوط ښارونه وُو چې د قبضې نه پاتې شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18696, 'Jeremiah 34:8', 'Jeremiah', 34, 8, '&nbsp;د مالِک خُدائ دا پېغام يرمياه ته ورکړے شو پس د دې نه چې صدقياه بادشاه او د يروشلم ټولو خلقو د غلامانو د آزادولو دپاره لوظ وکړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18697, 'Jeremiah 34:9', 'Jeremiah', 34, 9, '&nbsp;او ټولو په دې اتفاق وکړو چې هر څوک به خپل عبرانى غلامان او وينځې آزادوى، او هيڅ څوک به خپل د مُلک سړے يا ښځه بند نۀ ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18698, 'Jeremiah 34:10', 'Jeremiah', 34, 10, '&nbsp;ټولو مشرانو او خلقو چا چې هم دا لوظ کړے وو هغوئ دا خبره ومنله چې هغوئ به خپل غلامان او وينځې آزادوى او نور به هغوئ په خپله قبضه کښې نۀ ساتى او هغوئ يې آزاد کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18699, 'Jeremiah 34:11', 'Jeremiah', 34, 11, '&nbsp;خو وروستو هغوئ خپله فېصله بدله کړه، هغوئ آزاد شوى غلامان واپس راوستل او هغوئ يې بيا په زور سره دوباره خپل غلامان او وينځې جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18700, 'Jeremiah 34:12', 'Jeremiah', 34, 12, '&nbsp;نو بيا د مالِک خُدائ کلام په يرمياه نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');